package com.cpf.starter.smb;import org.springframework.boot.context.properties.ConfigurationProperties;@ConfigurationProperties("cpf.integration.smb") public class CpfSmbProperties {private boolean enabled;private String host,share,domain="",username,password;private long maxBytes=1073741824;public boolean isEnabled(){return enabled;}public void setEnabled(boolean v){enabled=v;}public String getHost(){return host;}public void setHost(String v){host=v;}public String getShare(){return share;}public void setShare(String v){share=v;}public String getDomain(){return domain;}public void setDomain(String v){domain=v;}public String getUsername(){return username;}public void setUsername(String v){username=v;}public String getPassword(){return password;}public void setPassword(String v){password=v;}public long getMaxBytes(){return maxBytes;}public void setMaxBytes(long v){maxBytes=v;}public void validate(){if(!enabled)return;if(host==null||share==null||username==null||password==null||maxBytes<1)throw new IllegalStateException("SMB config required");}}
